'use strict';
const $=id=>document.getElementById(id),KEY='mil-noites-v1',validStatuses=['pending','reading','done'];
let readings=[],state={records:{},day:1},view='night',page=1,selected=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Não foi possível salvar neste navegador. Exporte um backup antes de sair.');return false}}
function record(id){return state.records[id]||{status:'pending'}}
function update(id,patch){state.records[id]={...record(id),...patch};save();render()}
function statusSelect(r){return `<select data-status="${r.id}" aria-label="Progresso de ${esc(r.title)}">${[['pending','Pendente'],['reading','Em andamento'],['done','Concluída']].map(([v,t])=>`<option value="${v}" ${record(r.id).status===v?'selected':''}>${t}</option>`).join('')}</select>`}
function searchUrl(r){const v=record(r.id);return 'https://www.google.com/search?q='+encodeURIComponent(`${v.ptTitle||r.title} ${r.author} tradução português brasileiro`)}
function favorite(r){return `<button class="star ${record(r.id).favorite?'selected':''}" data-fav="${r.id}" aria-label="${record(r.id).favorite?'Remover dos':'Adicionar aos'} favoritos: ${esc(r.title)}" aria-pressed="${!!record(r.id).favorite}">${icon('star')}</button>`}
function card(r){const v=record(r.id),n=['Conto','Poema','Ensaio'].indexOf(r.kind)+1;return `<article class="reading ${v.status==='done'?'completed':''}" data-kind="${r.kind}"><span class="reading-number">0${n}</span><span class="reading-icon"><img src="assets/${{Conto:'conto',Poema:'poema',Ensaio:'ensaio'}[r.kind]}-gravura.webp" alt="" width="96" height="96" decoding="async"></span><div class="reading-content"><span class="genre">${r.kind}</span><h2>${esc(r.title)}</h2><p class="author">${esc(r.author)}</p>${v.ptTitle?`<p class="translation-title">Em português: ${esc(v.ptTitle)}</p>`:''}<div class="actions"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Abrir original</a><a href="${esc(searchUrl(r))}" target="_blank" rel="noopener noreferrer">Buscar em português</a><button class="details-button" data-detail="${r.id}">Anotações e versão${v.notes?'<span class="note-mark" aria-label="Contém anotações"></span>':''}</button>${safeUrl(v.ptUrl)?`<a href="${esc(safeUrl(v.ptUrl))}" target="_blank" rel="noopener noreferrer">${v.confirmed?'Versão conferida':'Versão salva'}</a>`:''}</div>${v.completedAt&&v.status==='done'?`<p class="date">Concluída em ${new Date(v.completedAt).toLocaleDateString('pt-BR')}</p>`:''}</div><div class="reading-state">${favorite(r)}${statusSelect(r)}</div></article>`}
function firstPending(start=1){for(let d=start;d<=1000;d++)if(readings.some(r=>r.day===d&&record(r.id).status!=='done'))return d;return null}
function render(){const done=readings.filter(r=>record(r.id).status==='done').length;let complete=0;for(let d=1;d<=1000;d++)if(readings.filter(r=>r.day===d).every(r=>record(r.id).status==='done'))complete++;
$('done').textContent=done.toLocaleString('pt-BR');$('nights').textContent=complete;$('progress').value=done;
$('night-view').hidden=view!=='night';$('library-view').hidden=view!=='library';for(const [id,v] of [['today','night'],['library','library']]){$(id).classList.toggle('active',view===v);$(id).setAttribute('aria-pressed',view===v)}
const rs=readings.filter(r=>r.day===state.day);$('night-title').innerHTML=`Noite ${state.day} <span>de 1.000</span>`;$('night-count').textContent=`${rs.filter(r=>record(r.id).status==='done').length} de 3 leituras concluídas`;$('day').value=state.day;$('previous').disabled=state.day<=1;$('next').disabled=state.day>=1000;$('cards').innerHTML=rs.map(card).join('');if(view==='library')renderLibrary()}
function filtered(){const q=$('search').value.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return readings.filter(r=>{const v=record(r.id);return (!q||`${r.title} ${r.author} ${v.ptTitle||''}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q))&&(!$('kind').value||r.kind===$('kind').value)&&(!$('status-filter').value||v.status===$('status-filter').value)&&(!$('favorites').checked||v.favorite)})}
function renderLibrary(){const all=filtered(),pages=Math.max(1,Math.ceil(all.length/24));page=Math.min(page,pages);$('results-count').textContent=`${all.length.toLocaleString('pt-BR')} ${all.length===1?'leitura':'leituras'}`;$('results').innerHTML=all.length?all.slice((page-1)*24,page*24).map(r=>`<article class="row"><button class="night-link" data-day="${r.day}" aria-label="Ir para a noite ${r.day}"><span>Noite</span><strong>${r.day}</strong></button><div class="row-content"><span class="genre">${r.kind}</span><button class="row-title" data-detail="${r.id}">${esc(r.title)}</button><p>${esc(r.author)}</p></div><div class="reading-state">${favorite(r)}${statusSelect(r)}</div></article>`).join(''):'<p class="empty">Nenhuma leitura encontrada. Experimente mudar os filtros.</p>';$('page-label').textContent=`Página ${page} de ${pages}`;$('page-prev').disabled=page===1;$('page-next').disabled=page===pages}
function goDay(d){state.day=Math.max(1,Math.min(1000,Math.round(Number(d)||1)));view='night';save();render()}
function details(id){selected=readings.find(r=>r.id===id);if(!selected)return;const v=record(id);$('detail-kind').textContent=`NOITE ${selected.day} · ${selected.kind.toUpperCase()}`;$('detail-title').textContent=selected.title;$('detail-author').textContent=selected.author;for(const [el,key] of [['notes','notes'],['pt-title','ptTitle'],['pt-url','ptUrl'],['edition','edition']])$(el).value=v[key]||'';$('confirmed').checked=!!v.confirmed;$('save-error').textContent='';$('details').showModal()}
function validateBackup(data){if(!data||data.format!=='mil-noites'||data.version!==1||!data.state||typeof data.state.records!=='object'||!data.state.records||Array.isArray(data.state.records))throw Error('Formato de backup inválido.');const known=new Set(readings.map(r=>r.id)),clean={};for(const [id,r] of Object.entries(data.state.records)){if(!known.has(id)||!r||!validStatuses.includes(r.status))throw Error('O backup contém leituras ou estados inválidos.');const c={status:r.status,favorite:!!r.favorite,confirmed:!!r.confirmed};for(const k of ['notes','ptTitle','ptUrl','edition']){if(r[k]!==undefined&&typeof r[k]!=='string')throw Error('O backup contém campos inválidos.');c[k]=(r[k]||'').slice(0,50000)}if(c.ptUrl&&!safeUrl(c.ptUrl))throw Error('O backup contém um link inválido.');if(r.completedAt){if(Number.isNaN(Date.parse(r.completedAt)))throw Error('Data inválida no backup.');c.completedAt=r.completedAt}clean[id]=c}return {records:clean,day:Math.max(1,Math.min(1000,Math.round(Number(data.state.day)||1)))}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.fav)update(b.dataset.fav,{favorite:!record(b.dataset.fav).favorite});if(b.dataset.detail)details(b.dataset.detail);if(b.dataset.day)goDay(b.dataset.day)});
document.addEventListener('change',e=>{const id=e.target.dataset.status;if(id){const status=e.target.value;update(id,{status,completedAt:status==='done'?new Date().toISOString():null})}});
$('today').onclick=()=>{view='night';render()};$('library').onclick=()=>{view='library';render()};$('previous').onclick=()=>goDay(state.day-1);$('next').onclick=()=>goDay(state.day+1);$('day').onchange=()=>goDay($('day').value);$('resume').onclick=()=>{const d=firstPending();if(d)goDay(d);else toast('Você concluiu as 1.000 noites!')};$('next-pending').onclick=()=>{const d=firstPending(state.day+1)||firstPending();if(d)goDay(d);else toast('Todas as leituras foram concluídas!')};
for(const id of ['search','kind','status-filter','favorites'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderLibrary()});$('page-prev').onclick=()=>{page--;renderLibrary()};$('page-next').onclick=()=>{page++;renderLibrary()};
$('save').onclick=()=>{const u=$('pt-url').value.trim();if(u&&!safeUrl(u)){$('save-error').textContent='Informe um link completo que comece com https:// ou http://.';return}if($('confirmed').checked&&!u){$('save-error').textContent='Adicione o link da versão que você conferiu.';return}update(selected.id,{notes:$('notes').value,ptTitle:$('pt-title').value.trim(),ptUrl:u,edition:$('edition').value.trim(),confirmed:$('confirmed').checked});$('details').close();toast('Anotações e versão salvas.')};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'mil-noites',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`mil-noites-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Backup exportado.')};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('O arquivo é grande demais para um backup.');const next=validateBackup(JSON.parse(await f.text()));if(!window.confirm('Importar este backup substituirá o progresso atual neste navegador. Deseja continuar?'))return;state=next;save();render();toast('Backup importado.')}catch(e){toast(e.message||'Não foi possível importar o backup.')}finally{$('file').value=''}};
$('theme').value=document.documentElement.dataset.theme||'light';
$('theme').onchange=()=>{const theme=$('theme').value;document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#141b29':'#334d80';try{localStorage.setItem('mil-noites-theme',theme)}catch{toast('O tema foi aplicado, mas não foi possível salvar a preferência.')}};
async function init(){try{const response=await fetch('readings.json');if(!response.ok)throw Error();readings=await response.json();try{const stored=localStorage.getItem(KEY);if(stored)state=validateBackup({format:'mil-noites',version:1,state:JSON.parse(stored)})}catch{toast('Não foi possível recuperar o progresso salvo. Você pode importar um backup.')}render();registerTools()}catch{$('cards').innerHTML='<p>Não foi possível carregar o programa. Recarregue a página para tentar novamente.</p>'}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'get_reading_progress',description:'Read the current night and completion counts without changing progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({night:state.day,completed:readings.filter(r=>record(r.id).status==='done').length,total:3000})},{name:'set_reading_status',description:'Set one listed reading to pending, reading, or done, and update the visible progress.',inputSchema:{type:'object',properties:{id:{type:'string'},status:{type:'string',enum:validStatuses}},required:['id','status'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!readings.some(r=>r.id===input.id)||!validStatuses.includes(input.status))throw Error('Invalid reading or status');update(input.id,{status:input.status,completedAt:input.status==='done'?new Date().toISOString():null});return {id:input.id,status:record(input.id).status}}}];for(const t of tools)try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
init();
